import {createRepository,installRepository} from './repository.js';
export async function connectRepository({fetcher=fetch,onStatus=()=>{},onAuth=()=>{location.replace('/login')}}={}){
 let error='',pending=0,failed=false,tail=Promise.resolve(),revision,csrf,identity,remote,memory=null,localRepo;
 const clear=()=>{memory=JSON.stringify({version:2,players:[],games:[]});remote=null;localRepo?.read();};
 async function request(path,options={}){const res=await fetcher(path,{...options,credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...options.headers}});if(!res.ok){const message=await res.text();if(res.status===401||res.status===403){clear();onAuth(res.status);}throw Error(message||`저장 실패 (${res.status})`);}return res.status===204?null:res.json();}
 identity=await request('/api/session');csrf=identity.csrf;
 const initial=await request('/api/data');revision=initial.revision;remote=initial.data;
 memory=JSON.stringify(remote);let ready=false;
 const status=()=>onStatus({pending,error,failed});
 const storage={getItem:key=>key==='volleyball-system-v2'?memory:null,setItem(key,value){if(key!=='volleyball-system-v2')return;memory=value;if(!ready)return;const snapshot=JSON.parse(value);pending++;status();tail=tail.then(async()=>{try{if(failed)return;const changes={version:2,players:[],games:[],deletePlayers:[],deleteGames:[]};for(const key of ['players','games']){const before=new Map(remote[key].map(x=>[x.id,x]));for(const entity of snapshot[key]){if(JSON.stringify(before.get(entity.id))!==JSON.stringify(entity))changes[key].push(entity);before.delete(entity.id);}changes[key==='players'?'deletePlayers':'deleteGames']=[...before.keys()];}const result=await request('/api/data',{method:'PUT',body:JSON.stringify({revision,data:changes})});revision=result.revision;remote=snapshot;}catch(e){failed=true;error='저장 실패: '+e.message;}finally{pending--;status();}});}};
 const repo=createRepository(storage);localRepo=repo;ready=true;
 const result={...repo,getError:()=>error||repo.getError(),async flush(){await tail;if(failed)throw Error(error);},isPending:()=>pending>0,async checkSession(){const s=await request('/api/session');if(s.userId!==identity.userId){clear();onAuth(401);throw Error('계정이 변경되었습니다. 다시 불러오세요.');}},async refresh(){await this.flush();await this.checkSession();const latest=await request('/api/data');const changed=revision!==latest.revision;revision=latest.revision;remote=latest.data;memory=JSON.stringify(remote);return changed;},backup:()=>({format:'hwaiq-backup-v1',exportedAt:new Date().toISOString(),data:memory?JSON.parse(memory):null}),async importData(data,confirmLogin){await this.flush();const response=await request('/api/import',{method:'PUT',body:JSON.stringify({revision,data,confirmLogin})});revision=response.revision;remote=data;memory=JSON.stringify(data);},async logout(discard=false){if(!discard)await this.flush();await request('/api/auth/logout',{method:'POST'});clear();onAuth(401);},identity};
 installRepository(result);return result;
}
